SELECT country_group, rating_bucket, min_rating, us_rating FROM (SELECT CASE WHEN country IN ('JP', 'DE') THEN 'group_a' ELSE 'other' END AS country_group, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(rating) AS min_rating, SUM(CASE WHEN country = 'US' THEN rating ELSE 0 END) AS us_rating FROM suppliers GROUP BY CASE WHEN country IN ('JP', 'DE') THEN 'group_a' ELSE 'other' END, CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END) AS agg WHERE us_rating > 25
